{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Intentful aromatherapy</title>
  <meta name="description" content="Gentle aromatherapy sessions and micro-practices that may support calm, focus, and restful nights. Book a session or explore blends and plans.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="brand">
      <svg class="logo" width="48" height="48" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="8" fill="#F6F0EA"></rect><circle cx="24" cy="18" r="6" fill="#C7E5D7"></circle><rect x="12" y="28" width="24" height="6" rx="3" fill="#E8C9D0"></rect></svg>
      <div>
        <span class="site-name">{{BUSINESS_NAME}}</span>
        <small class="tag">{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="main-nav">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Signature Blends</a>
      <a href="shop.html">Apothecary</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Why Scent</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
    <a class="cta primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    <button class="nav-toggle" aria-label="Open menu">☰</button>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" style="background-image: url('assets/img/pattern.svg')">
      <div class="hero-inner">
        <h1>Intentful scent sessions that may support everyday clarity</h1>
        <p class="lede">Short, safety-minded aromatherapy experiences and micro-practices you can fold into the day. Sessions and blends informed by scent chemistry and gentle ritual.</p>
        <div class="hero-actions">
          <a class="btn" href="book.html">Reserve a time</a>
          <a class="btn ghost" href="services.html">Explore offerings</a>
        </div>
      </div>
    </section>

    <!-- DIAGNOSTIC -->
    <section id="diagnostic" class="diagnostic">
      <div class="diag-inner">
        <h2>How are you feeling right now?</h2>
        <p class="small">Choose a mood to receive a short, scent-forward approach you can try immediately. No medical claims — may support mood and routine.</p>
        <div class="mood-grid" aria-label="Mood selector">
          <button class="mood" data-key="grounded">Tired &amp; Slow</button>
          <button class="mood" data-key="uplifted">Stressed &amp; Wired</button>
          <button class="mood" data-key="focus">Scattered &amp; Distracted</button>
          <button class="mood" data-key="rest">Restless &amp; Wakeful</button>
        </div>
        <div class="mood-recommendation" id="mood-reco">
          <h3 class="reco-title">Suggested approach</h3>
          <p class="reco-desc">Select a mood to see a short scent method and a focused micro-ritual you can use now.</p>
          <a id="mood-cta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>
    </section>

    <!-- PLAN -->
    <section id="plan" class="plan">
      <div class="plan-inner">
        <h2>Approach snapshots</h2>
        <p class="small">Short outlines of what to expect from a single session or a curated blend. Safety notes and dilution guidance included in FAQs.</p>

        <!-- second Mood-to-Method (different placement) -->
        <div class="mood-mini">
          <label for="mood-select">Choose mood</label>
          <select id="mood-select">
            <option value="grounded">Tired &amp; Slow</option>
            <option value="uplifted">Stressed &amp; Wired</option>
            <option value="focus">Scattered &amp; Distracted</option>
            <option value="rest">Restless &amp; Wakeful</option>
          </select>
          <div id="mood-card" class="card">
            <h4 id="mood-card-title">Gentle Unwind</h4>
            <p id="mood-card-text">A brief inhalation practice with a low-dilution floral-citrus roll-on you can make or receive during a session.</p>
            <a id="mood-card-cta" class="btn ghost" href="book.html">Book a calm-collection</a>
          </div>
        </div>

        <div class="approach-list">
          <article class="approach">
            <h3>Mini Session — "Evening Ease"</h3>
            <p class="desc">A 25-minute guided inhalation and diffusion session designed to support unwinding. Includes a small sachet blend.</p>
          </article>
          <article class="approach">
            <h3>Guided Pairing — "Midday Reset"</h3>
            <p class="desc">A 45-minute consultive session focused on portable practices and a take-home spray that may support focus.</p>
          </article>
          <article class="approach">
            <h3>Curated Blend Lab — "Personal Blend"</h3>
            <p class="desc">A 75-minute immersive session for creating a personalized blend, with dilution notes and usage plan.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- MICRO HABITS -->
    <section id="micro" class="micro-habits">
      <div class="micro-inner">
        <h2>Micro practices to fold into routine</h2>
        <ul>
          <li><strong>Three-breath inhale:</strong> Inhale a subtle scent for three simple breaths before starting work.</li>
          <li><strong>Doorway spritz:</strong> A quick, low-dilution spray on your scarf or wrist to mark transitions.</li>
          <li><strong>Night veil:</strong> A small diffuser or cotton pad with a mild sleepy-support blend near your pillow (low concentration).</li>
        </ul>
        <p class="note">Always patch-test new blends and follow dilution guidance. Avoid certain oils during pregnancy or around sensitive pets — see FAQ.</p>
      </div>
    </section>

    <!-- PRICING -->
    <section id="pricing" class="pricing">
      <div class="pricing-inner">
        <h2>Plans &amp; single sessions</h2>
        <p class="small">Toggle between monthly support and single-session package pricing.</p>

        <div class="price-toggle">
          <span>Monthly</span>
          <label class="switch">
            <input id="priceToggle" type="checkbox">
            <span class="slider"></span>
          </label>
          <span>Packages</span>
        </div>

        <div class="pricing-grid">
          <div class="price-card">
            <h3>Seed Plan</h3>
            <div class="price" data-monthly="29" data-package="85">$29</div>
            <p class="desc">A small monthly practice kit and a 30-minute check-in. May support steady routine.</p>
            <a class="btn" href="book.html">Start Seed</a>
          </div>

          <div class="price-card featured">
            <h3>Anchor Membership</h3>
            <div class="price" data-monthly="69" data-package="195">$69</div>
            <p class="desc">Monthly guided session plus blends and a short ritual plan. Designed for consistent care.</p>
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Join Anchor</a>
          </div>

          <div class="price-card">
            <h3>Blend Lab Pass</h3>
            <div class="price" data-monthly="0" data-package="275">$275</div>
            <p class="desc">One-off in-depth blend session with full dilution notes and take-home formula.</p>
            <a class="btn" href="book.html">Book Lab</a>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta">
      <div>
        <h2>Ready for a small, practical step?</h2>
        <p class="small">Short sessions and targeted blends — safety-first, pet-aware, and clear dilution guidance provided.</p>
        <a class="btn large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

    <!-- FOOTER / FAQ SNIPPET -->
    <footer class="site-footer">
      <div class="footer-inner">
        <div class="footer-col">
          <h4>Contact</h4>
          <p>Phone: {{PHONE}}<br>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p>{{CITY}}, {{STATE}}</p>
        </div>
        <div class="footer-col">
          <h4>Quick links</h4>
          <a href="about.html">About</a>
          <a href="pricing.html">Plans</a>
          <a href="book.html">Book</a>
        </div>
        <div class="footer-col">
          <h4>FAQ — safety notes</h4>
          <ul>
            <li>Always dilute essential oils for topical use; follow provided dilution percentages.</li>
            <li>Patch test new blends on a small skin area and wait 24 hrs.</li>
            <li>Some oils are not recommended during pregnancy; consult a qualified provider.</li>
            <li>Keep blends away from pets and follow species-safe guidance; avoid diffusing certain oils around cats.</li>
          </ul>
        </div>
      </div>
      <div class="copyright">© <span id="year"></span> {{BUSINESS_NAME}} — All rights reserved.</div>
    </footer>
  </main>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
