{"path":"assets/css/styles.css","content":"/* Core styles for aromatherapy template */
:root{
  --bg:#fbf9f7; --muted:#6b6b6b; --accent:#C7E5D7; --accent-2:#E8C9D0; --brand:#2c6f5e; --card:#fff;
  --radius:10px; --shadow:0 8px 24px rgba(28,30,34,0.06);
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial; background:var(--bg); color:#222; line-height:1.45}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;background:linear-gradient(180deg,rgba(255,255,255,0.9),transparent);position:sticky;top:0;z-index:40}
.brand{display:flex;gap:12px;align-items:center}
.site-name{font-weight:700;display:block}
.tag{display:block;color:var(--muted);font-size:12px}
.main-nav{display:flex;gap:14px}
.main-nav a{color:#2b2b2b;text-decoration:none;font-size:15px}
.cta.primary{background:var(--brand);color:#fff;padding:8px 14px;border-radius:8px;text-decoration:none}
.nav-toggle{display:none;background:none;border:0;font-size:20px}
.hero{padding:60px 20px;background-repeat:repeat; background-size:220px;}
.hero-inner{max-width:980px;margin:0 auto;padding:48px;background:linear-gradient(180deg, rgba(255,255,255,0.85), rgba(255,255,255,0.6));border-radius:14px;box-shadow:var(--shadow)}
.hero h1{margin:0 0 10px;font-size:28px}
.lede{color:var(--muted);margin:0 0 18px}
.hero-actions .btn{margin-right:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;background:#fff;border:1px solid #e5e5e5;color:#222;text-decoration:none}
.btn.ghost{background:transparent;border:1px solid rgba(0,0,0,0.06)}
.btn.primary{background:var(--brand);color:#fff;border:0}
.btn.large{padding:14px 20px;font-size:18px}
.small{color:var(--muted)}
.diagnostic{padding:42px 20px}
.diag-inner{max-width:980px;margin:0 auto}
.mood-grid{display:flex;gap:10px;margin:12px 0}
.mood{background:#fff;border-radius:10px;padding:12px 16px;border:1px solid #f0f0f0;cursor:pointer}
.mood:focus{outline:3px solid rgba(44,111,94,0.12)}
.mood-recommendation{margin-top:16px;padding:16px;background:var(--card);border-radius:12px;box-shadow:var(--shadow)}
.plan{padding:30px 20px}
.plan-inner{max-width:980px;margin:0 auto}
.mood-mini{display:flex;gap:12px;align-items:flex-start}
.mood-mini label{font-size:13px}
.card{background:#fff;padding:12px;border-radius:10px;box-shadow:var(--shadow);max-width:360px}
.approach-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;margin-top:16px}
.approach{background:#fff;padding:14px;border-radius:10px}
.micro-habits{padding:26px 20px;background:linear-gradient(180deg,rgba(231,245,241,0.6),transparent)}
.micro-inner{max-width:980px;margin:0 auto}
.pricing{padding:40px 20px}
.price-toggle{display:flex;gap:12px;align-items:center;justify-content:center;margin-bottom:18px}
.switch{position:relative;display:inline-block;width:44px;height:24px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#ddd;border-radius:34px}
.slider:before{position:absolute;content:"";height:18px;width:18px;left:3px;bottom:3px;background:white;transition:0.25s;border-radius:50%}
.switch input:checked + .slider{background:var(--brand)}
.switch input:checked + .slider:before{transform:translateX(20px)}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;max-width:1000px;margin:0 auto}
.price-card{background:#fff;padding:18px;border-radius:12px;text-align:center}
.price-card.featured{border:2px solid rgba(44,111,94,0.08)}
.price{font-size:28px;font-weight:700;margin:8px 0;color:var(--brand)}
.final-cta{padding:36px 20px;text-align:center}
.site-footer{background:#fff;padding:22px 20px;margin-top:28px}
.footer-inner{display:flex;gap:24px;flex-wrap:wrap;max-width:1000px;margin:0 auto}
.footer-col{flex:1;min-width:200px}
.footer-col a{display:block;color:var(--muted);text-decoration:none}
.copyright{max-width:1000px;margin:12px auto;color:var(--muted);font-size:13px}
@media(max-width:800px){
  .main-nav{display:none}
  .nav-toggle{display:block}
  .hero-inner{padding:28px}
}
/* Number animation hint */
.price.animate{transition:transform 0.28s}
"}
{"path":"assets/js/main.js","content":"(function(){
  // Utilities
  function q(sel, ctx){return (ctx||document).querySelector(sel)}
  function qa(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Year
  q('#year').textContent = new Date().getFullYear();

  // Pricing toggle with animated numbers
  var toggle = q('#priceToggle');
  var priceEls = qa('.price');

  function animateValue(el, start, end, duration){
    var startTimestamp = null; var step = function(timestamp){
      if(!startTimestamp) startTimestamp = timestamp;
      var progress = Math.min((timestamp - startTimestamp) / duration, 1);
      var value = Math.round(start + (end - start) * easeOutCubic(progress));
      el.textContent = '$' + value + (el.dataset.suffix||'');
      if(progress < 1){
        window.requestAnimationFrame(step);
      }
    };
    window.requestAnimationFrame(step);
  }
  function easeOutCubic(t){return (--t)*t*t+1}

  function updatePrices(usePackage){
    priceEls.forEach(function(el){
      var monthly = parseInt(el.dataset.monthly,10) || 0;
      var pack = parseInt(el.dataset.package,10) || 0;
      var from = parseInt(el.textContent.replace(/[^0-9]/g,''),10) || (usePackage?monthly:pack);
      var to = usePackage ? pack : monthly;
      // handle 0 as literal (e.g., not a subscription)
      animateValue(el, from, to, 520);
      el.classList.add('animate');
      setTimeout(function(){el.classList.remove('animate')},600);
    });
  }

  // Initialize prices to monthly by default
  window.addEventListener('load', function(){
    priceEls.forEach(function(el){ el.textContent = '$' + (el.dataset.monthly || '0'); el.dataset.suffix = ''; });
  });

  toggle.addEventListener('change', function(e){ updatePrices(e.target.checked); });

  // Mood-to-Method mapping
  var moodMap = {
    grounded: {
      title: 'Gentle Grounding',
      desc: 'A warm, slightly resinous blend for steady breathing: slow three breaths with mindful focus. Use a low-dilution roll-on or a single inhalation from a tissue. Patch-test first.',
      cta: 'Try a grounding ritual'
    },
    uplifted: {
      title: 'Cooling Rebalance',
      desc: 'A citrus-mint inhalation sequence to support settling from heightened stress. Keep dilution low and avoid direct face application.',
      cta: 'Explore calming approaches'
    },
    focus: {
      title: 'Clarify & Center',
      desc: 'A crisp herb-citrus pairing for focused breaths and short desk spritz. May support attention for short windows without clinical claims.',
      cta: 'Get a focus mini-session'
    },
    rest: {
      title: 'Soothing Wind-down',
      desc: 'A soft, floral base in very low dilution for pre-sleep routine. Use near-sleep diffusion at low intensity; avoid direct skin if sensitive.',
      cta: 'Start a sleep-friendly practice'
    }
  };

  // First mood selector (buttons)
  qa('.mood').forEach(function(btn){
    btn.addEventListener('click', function(){
      var key = btn.dataset.key;
      var data = moodMap[key];
      if(!data) return;
      var reco = q('#mood-reco');
      q('.reco-title', reco).textContent = data.title || '';
      q('.reco-desc', reco).textContent = data.desc || data.desc;
      var cta = q('#mood-cta');
      cta.textContent = data.cta || '{{PRIMARY_CTA_LABEL}}';
      // subtle pulse animation
      reco.animate([{transform:'translateY(6px)',opacity:0},{transform:'translateY(0)',opacity:1}],{duration:220,easing:'ease-out'});
    });
  });

  // Second mood selector (select) updates card
  var select = q('#mood-select');
  if(select){
    select.addEventListener('change', function(){
      var key = select.value; var data = moodMap[key] || {};
      q('#mood-card-title').textContent = data.title || '';
      q('#mood-card-text').textContent = data.desc || '';
      q('#mood-card-cta').textContent = data.cta || '{{PRIMARY_CTA_LABEL}}';
    });
  }

  // Simple nav toggle for small screens
  var navToggle = q('.nav-toggle');
  navToggle && navToggle.addEventListener('click', function(){
    var nav = q('.main-nav');
    if(nav.style.display === 'flex'){ nav.style.display='none'; } else { nav.style.display='flex'; nav.style.flexDirection='column'; }
  });

})();"} 
